for (PDDocument i : infiles) 
i.close(); 
Thread.currentThread().sleep(1000); 
System.err.println("All closed: "+instance.totalMemory()); 
(new java.util.Scanner(System.in)).nextLine(); 
System.err.println("Finish: "+instance.totalMemory()); 
